def get_nearest_empty_seat(people_positions, empty_seats):
    nearest_count = float('inf')
    nearest_positions = []

    for person in people_positions:
        distances = [euclidean_distance(person[0], person[1], seat[0], seat[1]) for seat in empty_seats]
        min_distance = min(distances)

        if min_distance < nearest_count:
            nearest_count = min_distance
            nearest_positions = [empty_seats[i] for i, d in enumerate(distances) if d == min_distance]
        elif min_distance == nearest_count:
            nearest_positions.extend([empty_seats[i] for i, d in enumerate(distances) if d == min_distance])

    return nearest_count, nearest_positions

def solve_tram_explosions(tram_layout):
    R, C = len(tram_layout), len(tram_layout[0])
    people_positions = []
    empty_seats = []

    for i in range(R):
        for j in range(C):
            if tram_layout[i][j] == 'X':
                people_positions.append((i, j))
            elif tram_layout[i][j] == 'L':
                empty_seats.append((i, j))

    total_explosions = 0

    while people_positions:
        _, nearest_positions = get_nearest_empty_seat(people_positions, empty_seats)

        if len(nearest_positions) == 1:
            empty_seats.remove(nearest_positions[0])
            people_positions.remove(min(people_positions, key=lambda p: (p[0], p[1])))
        else:
            total_explosions += 1
            people_positions = [person for person in people_positions if person not in nearest_positions]
            empty_seats = [seat for seat in empty_seats if seat not in nearest_positions]

    return total_explosions

