import sys

def count_explosions(tram: List[List[str]]) -> int:
    R, C = len(tram), len(tram[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def get_distance(x1, y1, x2, y2):
        return math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

    def find_all_l_and_x():
        l_positions = []
        x_positions = []
        for i in range(R):
            for j in range(C):
                if tram[i][j] == 'L':
                    l_positions.append((i, j))
                elif tram[i][j] == 'X':
                    x_positions.append((i, j))
        return l_positions, x_positions

    def bfs(start_x, start_y):
        queue = [(-get_distance(start_x, start_y, lx, ly), lx, ly) for lx, ly in l_positions]
        heapq.heapify(queue)
        visited = set()
        while queue:
            dist, cx, cy = heapq.heappop(queue)
            if (cx, cy) in visited:
                continue
            visited.add((cx, cy))
            if tram[cx][cy] == 'L':
                return True, dist
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < R and 0 <= ny < C and (nx, ny) not in visited:
                    heapq.heappush(queue, (-dist, nx, ny))
        return False, None

    l_positions, x_positions = find_all_l_and_x()
    explosions = 0

    for lx, ly in x_positions:
        found_seat, min_dist = bfs(lx, ly)
        if found_seat:
            explosions += 1
            # Mark the seat as taken
            for dx, dy in directions:
                nx, ny = lx + dx, ly + dy
                if 0 <= nx < R and 0 <= ny < C and tram[nx][ny] == 'L':
                    tram[nx][ny] = '.'
                    break

    return explosions

